DROP TABLE IF EXISTS `tb_animation`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
 SET character_set_client = utf8mb4 ;
CREATE TABLE `tb_animation` (
  `#` int(11) DEFAULT NULL,
  `id` int(11) DEFAULT NULL,
  `name` varchar(254) DEFAULT NULL,
  `shortcomment` varchar(254) DEFAULT NULL,
  `longcomment` varchar(254) DEFAULT NULL,
  `rating` double DEFAULT NULL,
  `releasedate` varchar(254) DEFAULT NULL,
  `status` int(11) DEFAULT NULL,
  `genre` varchar(512) DEFAULT NULL COMMENT '棰樻潗/Bangumi鏍囩鎽樿',
  `bcimg` varchar(254) DEFAULT NULL,
  `preview_video_url` varchar(512) DEFAULT NULL COMMENT '璇曠湅 PV 瑙嗛鍦板潃',
  `countpage` varchar(254) DEFAULT NULL,
  `voicer` varchar(254) DEFAULT NULL,
  `hengpic` varchar(254) DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '鏉＄洰鏇存柊鏃堕棿'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

