DROP TABLE IF EXISTS `tb_cartoons`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
 SET character_set_client = utf8mb4 ;
CREATE TABLE `tb_cartoons` (
  `#` int(11) DEFAULT NULL,
  `comicid` int(11) DEFAULT NULL,
  `name` varchar(254) DEFAULT NULL,
  `shortcomment` varchar(254) DEFAULT NULL,
  `longcomment` varchar(254) DEFAULT NULL,
  `author` varchar(254) DEFAULT NULL,
  `status` varchar(254) DEFAULT NULL,
  `genre` varchar(512) DEFAULT NULL COMMENT '棰樻潗/Bangumi鏍囩',
  `releasedate` varchar(32) DEFAULT NULL COMMENT '骞翠唤鎴栨棩鏈熷瓧绗︿覆',
  `rating` decimal(4,1) DEFAULT NULL COMMENT '璇勫垎',
  `picurl` varchar(254) DEFAULT NULL,
  `hengpic` varchar(254) DEFAULT NULL,
  `chaptercount` varchar(254) DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '鏇存柊鏃堕棿'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
