  `picurl` varchar(254) DEFAULT NULL,
  `hengpic` varchar(254) DEFAULT NULL,
  `chaptercount` int(11) DEFAULT NULL,
  `genre` varchar(512) DEFAULT NULL COMMENT '棰樻潗/Bangumi鏍囩',
  `status` varchar(16) DEFAULT '杩炶浇' COMMENT '杩炶浇/瀹岀粨',
  `releasedate` varchar(32) DEFAULT NULL,
  `rating` decimal(4,1) DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
